<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><p class="eyebrow"><a href="<?= site_url('admin/produk') ?>">Produk</a> / <?= $product?'Edit':'Tambah' ?></p><h1><?= esc($title) ?></h1><?php if(session()->getFlashdata('error')): ?><p class="alert alert-error"><?= esc(session()->getFlashdata('error')) ?></p><?php endif ?><form class="product-admin-form" method="post" enctype="multipart/form-data" action="<?= $product?site_url('admin/produk/'.$product['id']):site_url('admin/produk') ?>"><?= csrf_field() ?><label for="name">Nama produk</label><input id="name" name="name" required maxlength="160" value="<?= esc(old('name',$product['name']??'')) ?>"><label for="description">Deskripsi</label><textarea id="description" name="description" required rows="3"><?= esc(old('description',$product['description']??'')) ?></textarea><label for="composition">Komposisi</label><textarea id="composition" name="composition" required rows="3"><?= esc(old('composition',$product['composition']??'')) ?></textarea><label for="allergens">Alergen</label><input id="allergens" name="allergens" value="<?= esc(old('allergens',$product['allergens']??'')) ?>"><label for="storage_note">Saran penyimpanan</label><input id="storage_note" name="storage_note" value="<?= esc(old('storage_note',$product['storage_note']??'')) ?>"><label for="category_id">Kategori</label><select id="category_id" name="category_id" required><?php foreach($categories as $category): ?><option value="<?= (int)$category['id'] ?>" <?= old('category_id',$product['category_id']??'')==$category['id']?'selected':'' ?>><?= esc($category['name']) ?></option><?php endforeach ?></select><label for="variant_label">Ukuran/varian</label><input id="variant_label" name="variant_label" required value="<?= esc(old('variant_label',$variant['label']??'')) ?>"><label for="price">Harga (rupiah)</label><input id="price" name="price" type="number" min="1" required value="<?= esc(old('price',$variant['price']??'')) ?>"><label for="stock">Stok</label><input id="stock" name="stock" type="number" min="0" required value="<?= esc(old('stock',$variant['stock']??0)) ?>"><label for="image">Foto utama (JPG/PNG, maksimal 3 MB) <?= $product?'(opsional jika gambar lama dipakai)':'*' ?></label><input id="image" name="image" type="file" accept="image/jpeg,image/png" <?= $product?'':'required' ?>><label class="radio-row"><input type="checkbox" name="is_active" value="1" <?= !$product||$product['is_active']?'checked':'' ?>> Tampilkan di katalog</label><button class="button">Simpan produk</button></form><?= $this->endSection() ?>